<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { auth, notify } from '../state.js'
import { api } from '../api.js'
const data = ref(null), loading = ref(true), failed = ref(false), exportJobs=ref([]),exportBusy=ref(false),refreshing=ref(false)
const upcomingItems = computed(() => data.value?.upcoming_examinations?.map(x => typeof x === 'string' ? { title:x } : x) || data.value?.upcoming_schedule?.map(x => ({ title:x.examination, starts_at:x.starts_at })) || [])
let exportPoll, dashboardRefreshTimer
async function loadExportJobs(){if(auth.user?.role==='student')try{exportJobs.value=(await api.request('/student/exports')).items;if(!exportJobs.value.some(x=>['requested','processing'].includes(x.status))){clearInterval(exportPoll);exportPoll=undefined}}catch(e){notify(e.message,'danger')}}
async function requestExport(){exportBusy.value=true;try{const r=await api.request('/student/exports',{method:'POST'});notify(r.item.status==='completed'?'Export is ready to download.':r.item.safe_error||'Export request queued. You can keep working while it runs.',r.item.status==='failed'?'danger':'success');await loadExportJobs();if(exportJobs.value.some(x=>['requested','processing'].includes(x.status))&&!exportPoll)exportPoll=setInterval(loadExportJobs,3000)}catch(e){notify(e.message,'danger')}finally{exportBusy.value=false}}
async function downloadExport(job){try{await api.download(job.download_url,'examination-history.csv')}catch(e){notify(e.message,'danger')}}
async function refreshDashboard(){if(refreshing.value)return;refreshing.value=true;try{data.value=await api.dashboard();failed.value=false}catch(e){if(!data.value){failed.value=true;notify(e.message,'danger')}}finally{loading.value=false;refreshing.value=false}}
function onDashboardFocus(){if(auth.user?.role==='student')refreshDashboard()}
onBeforeUnmount(()=>{clearInterval(exportPoll);clearInterval(dashboardRefreshTimer);window.removeEventListener('focus',onDashboardFocus)})
onMounted(async()=>{await refreshDashboard();await loadExportJobs();if(auth.user?.role==='student'){dashboardRefreshTimer=setInterval(refreshDashboard,30000);window.addEventListener('focus',onDashboardFocus)}})
const descriptions = { courses: 'Across the institution', examinations: 'On the platform', students: 'Registered accounts', examiners: 'Academic staff', slots: 'Scheduled sessions', bookings: 'Student reservations', assigned_examinations: 'Assigned to you', booked_students: 'Across your slots', pending_evaluations: 'Awaiting review', available_examinations: 'Open for booking', upcoming_examinations: 'In your schedule', booked_slots: 'Confirmed reservations', published_results: 'Ready to view' }
const labels = { courses:'Courses', examinations:'Examinations', students:'Students', examiners:'Examiners', slots:'Examination slots', bookings:'Bookings', assigned_examinations:'Assigned examinations', booked_students:'Booked students', pending_evaluations:'Pending evaluations', available_examinations:'Available examinations', upcoming_examinations:'Upcoming examinations', booked_slots:'Booked slots', published_results:'Published results' }
</script>
<template><div class="page-heading"><div><div class="eyebrow">OVERVIEW</div><h1>Good day, {{ auth.user?.full_name?.split(' ')[0] }} <span class="wave">✳</span></h1><p class="muted">Here’s what’s happening in your workspace today.</p></div><div class="dashboard-actions"><button class="btn btn-sm btn-outline-primary" :disabled="refreshing" @click="refreshDashboard">{{refreshing?'Refreshing…':'Refresh'}}</button><div class="date-chip"><span>◷</span> {{ new Date().toLocaleDateString(undefined, { weekday:'short', month:'short', day:'numeric' }) }}</div></div></div>
  <div v-if="loading" class="loading-state"><div class="spinner-border spinner-border-sm text-primary"></div> Loading your dashboard…</div><div v-else-if="failed" class="empty-state"><div class="empty-icon">!</div><h3>Dashboard unavailable</h3><p>We couldn’t load your latest workspace information.</p><button class="btn btn-outline-primary" @click="$router.go(0)">Try again</button></div><template v-else>
    <div class="section-title"><h2>At a glance</h2><span class="live-label"><i></i> LIVE DATA</span></div><div class="stats-grid"><article v-for="(value,key) in data.stats" :key="key" class="stat-card"><div class="stat-top"><span class="stat-icon" :class="`tone-${key.charCodeAt(0)%4}`">{{ labels[key]?.[0] || '•' }}</span><span class="stat-dots">···</span></div><div class="stat-value">{{ value }}</div><div class="stat-name">{{ labels[key] || key }}</div><div class="stat-description">{{ descriptions[key] }}</div></article></div>
    <section v-if="auth.user?.role==='student'" class="panel-card examination-updates"><div class="panel-heading"><div><h3>Examination updates</h3><p>See exams being prepared, scheduled to open, or currently open for booking.</p></div><RouterLink to="/student/browse-examinations">Browse examinations <span>→</span></RouterLink></div><div v-if="data.examination_updates?.length" class="examination-update-list"><article v-for="exam in data.examination_updates" :key="exam.id" class="examination-update-row"><div><strong>{{exam.title}}</strong><small>{{exam.course_code}} · {{exam.type}}</small><small v-if="exam.phase==='preparing'">The examiner is preparing examination slots.</small><small v-else-if="exam.phase==='scheduled'">Booking opens {{new Date(exam.booking_start).toLocaleString()}}.</small><small v-else>Booking is open until {{new Date(exam.booking_end).toLocaleString()}}.</small></div><span class="exam-phase" :class="`phase-${exam.phase}`">{{exam.phase==='preparing'?'Preparing':exam.phase==='scheduled'?'Opening soon':'Open'}}</span></article></div><div v-else class="panel-empty"><strong>No examination updates yet</strong><span>Exams appear here while slots are being prepared or booking is active/scheduled.</span></div></section>
    <div class="lower-grid"><section class="panel-card"><div class="panel-heading"><div><h3>{{ auth.user?.role === 'admin' ? 'Upcoming examinations' : auth.user?.role === 'examiner' ? 'Your upcoming schedule' : 'Your upcoming examinations' }}</h3><p>Stay on top of what’s next</p></div><RouterLink v-if="auth.user?.role==='student'" to="/student/browse-examinations">Browse <span>→</span></RouterLink></div><div v-if="upcomingItems.length" class="list-rows"><div v-for="(exam,index) in upcomingItems" :key="exam.title+index" class="list-row"><span class="calendar-icon">▦</span><div><strong>{{ exam.title }}</strong><small>{{ exam.starts_at ? new Date(exam.starts_at).toLocaleString() : 'Scheduled examination' }}</small></div><span class="badge rounded-pill text-bg-light">Upcoming</span></div></div><div v-else class="panel-empty"><div class="empty-calendar">▦</div><strong>Nothing scheduled yet</strong><span>Your upcoming activity will appear here.</span></div></section>
      <section class="panel-card activity-card"><div class="panel-heading"><div><h3>Recent activity</h3><p>A quick look at recent changes</p></div><span class="activity-mark">↗</span></div><div v-if="data.recent_activity?.length" class="list-rows"><div v-for="item in data.recent_activity" :key="item.id" class="list-row"><div class="activity-dot"></div><div><strong>{{ item.action }}</strong><small>{{ item.created_at }}</small></div></div></div><div v-else class="panel-empty"><div class="activity-illustration">⌁</div><strong>You’re all caught up</strong><span>New activity will show up here.</span></div></section></div>
    <section v-if="auth.user?.role==='student'" class="panel-card export-panel"><div class="panel-heading"><div><h3>Examination history export</h3><p>Download your bookings and published marks as a CSV file.</p></div><button class="btn btn-primary" :disabled="exportBusy" @click="requestExport">{{exportBusy?'Requesting…':'Request export'}}</button></div><div v-if="!exportJobs.length" class="panel-empty"><strong>No export requests</strong><span>Request an export when you need an offline copy of your history.</span></div><div v-for="job in exportJobs" :key="job.job_id" class="export-job-row"><div><strong>{{job.status.replaceAll('_',' ')}}</strong><small>Requested {{new Date(job.created_at).toLocaleString()}}</small><span v-if="job.safe_error" class="text-danger">{{job.safe_error}}</span></div><button v-if="job.download_url" class="btn btn-sm btn-outline-primary" @click="downloadExport(job)">Download CSV</button></div></section>    <div class="dashboard-footer"><span><i></i> Connected to the Examination Management Portal</span><span>Student examination updates refresh automatically every 30 seconds</span></div>
  </template></template>

<style scoped>
.dashboard-actions{display:flex;align-items:center;gap:10px}.examination-updates{margin:16px 0}.examination-update-list{display:grid}.examination-update-row{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:12px 0;border-top:1px solid #edf1f5}.examination-update-row>div{display:grid;gap:4px}.examination-update-row strong{font-size:12px;color:#31465f}.examination-update-row small{font-size:10px;color:#8392a2}.exam-phase{border-radius:20px;padding:5px 9px;font-size:9px;font-weight:650;white-space:nowrap}.phase-preparing{background:#fff4e5;color:#a66d1d}.phase-scheduled{background:#edf3fa;color:#536f8e}.phase-open{background:#e8f7f1;color:#278567}@media(max-width:500px){.dashboard-actions{gap:5px;flex-direction:column;align-items:flex-end}.examination-update-row{align-items:flex-start}}
</style>
